// 1. Get the original intact job data from the Loop node
const originalJob = $('Loop Over Items').item.json;

// 2. Safely grab the AI's text output (handles different n8n AI node outputs)
const aiText = $json.text || $json.output || $json.message?.content || $json.response || "";

// 3. Clean and parse the AI JSON (strips markdown code blocks if the AI misbehaves)
let parsedAI = {};
try {
  const cleanText = aiText.replace(/```json/gi, '').replace(/```/g, '').trim();
  parsedAI = JSON.parse(cleanText);
} catch (e) {
  // Fallback to prevent workflow crashing if AI hallucinates formatting
  parsedAI = {
    required_skills: [],
    experience_required: "Error parsing AI data",
    salary: "",
    employment_type: "",
    location: "",
    remote: "",
    job_summary: "Error parsing AI data",
    ai_automation_relevance: ""
  };
}

// 4. MERGE original data with AI data to enforce Data Integrity
return {
  json: {
    ...originalJob,
    ...parsedAI
  }
};

