// 1. Grab scores and text fields from previous nodes (handling Airtable nested fields)
const inputData = $json.fields || $json;
const jobTitle = (inputData["Job Title"] || inputData.job_title || "").toLowerCase();
const experienceReq = (inputData["Experience Required"] || inputData.experience_required || "").toLowerCase();
const description = (inputData["Job Description"] || inputData.description || "").toLowerCase();

const skillScore = $json.skill_score || 0;
const relevanceScore = $json.relevance_score || 0;
const remoteScore = $json.remote_score || 0;

// 2. Check for entry-level friendliness or zero-experience openness
const isEntryLevelFriendly = 
  experienceReq.includes("entry level") || 
  experienceReq.includes("no experience") || 
  experienceReq.includes("zero experience") || 
  experienceReq.includes("fresh graduate") || 
  experienceReq.includes("0-1") || 
  experienceReq.includes("0–1") || 
  experienceReq.includes("trainee") || 
  experienceReq.includes("junior") || 
  description.includes("entry level") ||
  description.includes("no prior experience") ||
  description.includes("training provided");

// 3. Define your weighting matrix (total = 1.0)
const weightSkill = 0.4;       // Gives more weight to your personal tool stack
const weightRelevance = 0.4;
const weightRemote = 0.2;

// 4. Calculate base weighted overall job score (0 to 100)
let overallScore = (skillScore * weightSkill) + 
                   (relevanceScore * weightRelevance) + 
                   (remoteScore * weightRemote);

// 5. Apply an Entry-Level / Zero-Experience Boost (e.g., +15 point bonus)
let entryBoost = 0;
if (isEntryLevelFriendly) {
  entryBoost = 15;
}

// Combine score + boost and cap the maximum at 100
overallScore = Math.min(Math.round(overallScore + entryBoost), 100);

// 6. Return the item with the final score and entry-level flag
return {
  json: {
    ...$json,
    is_entry_level_friendly: isEntryLevelFriendly,
    job_score: overallScore
  }
};

const jobScore = Number($json.job_score || 0);

let recommendation;

if (jobScore >= 81) {
  recommendation = "APPLY";
} else if (jobScore >= 50) {
  recommendation = "CONSIDER";
} else {
  recommendation = "SKIP";
}

return {
  json: {
    ...$json,
    recommendation
  }
};

// Restore Job Data - Pairs incoming Airtable search results with original normalized jobs
const normalizedJobs = $('Normalize Job Payload').all();
const searchResults = $input.all();

return normalizedJobs.map((jobResult, index) => {
  const originalJob = jobResult.json;
  const searchItem = searchResults[index] ? searchResults[index].json : {};

  // Check if search returned a valid Airtable record with an ID
  const hasAirtableRecord = Boolean(searchItem.id || searchItem.id !== undefined && searchItem.fields);
  const airtableRecordId = searchItem.id || (searchItem.fields ? searchItem.id : null);

  return {
    json: {
      ...originalJob, // Preserves ALL original JobSpy & normalized fields intact
      airtable_record_id: airtableRecordId,
      duplicate_found: hasAirtableRecord
    }
  };
});

let draftText = "";
let rawOutput = $input.item.json.output;
if (!rawOutput) {
  rawOutput = $input.item.json.text;
}
if (!rawOutput) {
  rawOutput = $input.item.json;
}

if (typeof rawOutput === 'string') {
  const cleanStr = rawOutput.trim().replace(/^```json\s*|^```\s*|\s*```$/g, '');
  try {
    const parsed = JSON.parse(cleanStr);
    draftText = parsed.application_draft || parsed.text || cleanStr;
  } catch (e) {
    draftText = cleanStr;
  }
} else if (typeof rawOutput === 'object' && rawOutput !== null) {
  draftText = rawOutput.application_draft || rawOutput.text || JSON.stringify(rawOutput);
}

return {
  json: {
    ...$input.item.json,
    application_draft: draftText
  }
};
